mapper.select:
SELECT * FROM warehouse_stock WHERE warehouse_id = #{warehouseId} AND product_id IN
#{productId}
ORDER BY product_id, id FOR UPDATE

SELECT ws.id AS stock_id, ws.warehouse_id AS warehouse_id, ws.warehouse_name AS warehouse_name, ws.product_id AS product_id, ws.product_code AS product_code, ws.product_name AS product_name, ws.unit_name AS unit_name, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty, p.status AS product_status, ws.update_time AS update_time FROM warehouse_stock ws
AND ws.warehouse_id = #{warehouseId}
ORDER BY (p.safety_stock_qty - (ws.stock_qty - ws.locked_qty)) DESC LIMIT #{limit}

SELECT ws.id AS stock_id, ws.warehouse_name AS warehouse_name, ws.product_code AS product_code, ws.product_name AS product_name, ws.unit_name AS unit_name, p.quantity_precision AS quantity_precision, ws.stock_qty AS stock_qty, ws.locked_qty AS locked_qty, p.safety_stock_qty AS safety_stock_qty FROM warehouse_stock ws
AND ws.warehouse_id = #{warehouseId}
ORDER BY (p.safety_stock_qty - (ws.stock_qty - ws.locked_qty)) DESC LIMIT #{limit}

SELECT CASE WHEN ws.stock_qty = 0 THEN 'OUT_OF_STOCK' WHEN ws.stock_qty - ws.locked_qty <= 0 THEN 'NO_AVAILABLE' WHEN p.safety_stock_qty > 0 AND ws.stock_qty - ws.locked_qty <= p.safety_stock_qty THEN 'LOW_STOCK' ELSE 'NORMAL' END AS inventory_health, COUNT(*) AS stock_record_count FROM warehouse_stock ws INNER JOIN product p ON p.id = ws.product_id AND p.deleted = 0
ws.warehouse_id = #{warehouseId}
GROUP BY inventory_health
